"""Append the product-book policies RP-023..RP-032 to renewal_policies.json (idempotent).

    python add_book_policies.py

Re-index afterwards with index_renewal_policies.py (not run here).
"""
import json
import pathlib

P = pathlib.Path(__file__).resolve().parent / "renewal_policies.json"
NEW = [
 {"id": "RP-023", "category": "pricing_guardrail", "effective_date": "2026-08-01", "owner": "Head of Everyday Banking Products",
  "title": "Account Packages, Fees and Switching",
  "content": "SCOPE. Applies to every chequing package (Basic, Preferred, Ultimate, Student) and to any conversation about account fees.\n\nRULE 1 - FEE DISCLOSURE. Every package recommendation must state the monthly fee, the minimum-balance waiver (if any), the included transactions and the fee for extra transactions, in plain language and before the client agrees.\n\nRULE 2 - LOWEST-COST FIT. Advisors must recommend the lowest-cost package that fits the client's recorded usage over the last 12 months (transactions, balance, products held), even where this lowers the Bank's fee revenue. Show the expected annual saving.\n\nRULE 3 - NO SWITCH FEES. Changing package within the Bank carries no fee and no loss of account number. Fees already charged in the current month are not refunded unless approved under RP-018 Rule 2.\n\nRULE 4 - REGULATORY ANCHOR. Fee disclosure follows the Financial Consumer Agency of Canada (FCAC) guidance and the Bank Act disclosure requirements. A package upgrade that is promotional follows RP-011 consent rules."},
 {"id": "RP-024", "category": "risk_consideration", "effective_date": "2026-08-01", "owner": "Head of Client Care and Fair Treatment",
  "title": "Overdraft Protection and NSF Support",
  "content": "SCOPE. Applies to clients with non-sufficient-funds (NSF) items, frequent overdraft use, or in the Vulnerable wellness band.\n\nRULE 1 - SUPPORT FIRST. A client with any NSF item, or 10 or more overdraft days in the last 3 months, or in the Vulnerable band (RP-012), is offered support before anything else: a budgeting conversation, payment-date alignment and alerts. No product sale may be bundled into this contact.\n\nRULE 2 - FEE REFUNDS. An advisor may refund up to 2 NSF or overdraft fees per client per rolling 12 months without further approval. More refunds need Branch Manager approval and a documented hardship trigger (RP-014).\n\nRULE 3 - EXPRESS CONSENT. Overdraft protection may be added, or its limit raised, only with the client's express consent recorded before the change. Silence or a pre-checked box is not consent. Any message that mentions overdraft protection must say it is added only with the client's consent.\n\nRULE 4 - TONE. Communications are factual and non-judgemental and never mention internal wellness bands or scores (RP-016)."},
 {"id": "RP-025", "category": "approval_requirement", "effective_date": "2026-08-01", "owner": "VP Personal Lending",
  "title": "Debt Consolidation and Secured Lending Offers",
  "content": "SCOPE. Applies to consolidating card or other unsecured debt into a line of credit or loan, and to home-equity line re-advances.\n\nRULE 1 - SHOW BOTH WAYS. Any consolidation proposal must show, side by side, the total interest and the time to repay at the current minimum payment and under the proposed facility, and the new monthly payment.\n\nRULE 2 - AFFORDABILITY. A mortgage client may be offered consolidation or a re-advance only if the household TDS on the renewal payment is 44% or less (RP-013). A client without a mortgage may be offered consolidation only where the new monthly payment is lower than the current required payment.\n\nRULE 3 - SECURED LIMITS. A home-equity re-advance requires a combined loan-to-value (mortgage plus line limit) of 65% or less and is subject to adjudication.\n\nRULE 4 - NO PRESSURE. Never describe credit as pre-approved, never use urgency, and never make consolidation a condition of any other service. A client in the Vulnerable band (RP-012) or reporting hardship is routed to Client Assistance as a support conversation (RP-014) - no new credit is marketed."},
 {"id": "RP-026", "category": "regulatory_reference", "effective_date": "2026-08-01", "owner": "Chief Compliance Officer - Retail",
  "title": "Variable-Rate Credit - Rate Change Notices",
  "content": "SCOPE. Applies to every variable-rate line of credit and loan priced off the Bank's prime rate.\n\nRULE 1 - NOTICE WITHIN 30 DAYS. When the prime rate changes, every affected client is notified within 30 days with the new rate and the new or estimated monthly payment.\n\nRULE 2 - SHOW THE IMPACT. Notices show the effect of the change in dollars per month. Advisors may also show the effect of a further 25 basis-point move either way as illustration only - never as a forecast.\n\nRULE 3 - SERVICE, NOT SALES. A rate-change notice is a service communication (RP-011 Rule 2). It must contain no promotional offer, product recommendation or call to switch products.\n\nRULE 4 - HELP. Notices tell the client how to reach an advisor if the new payment is hard to manage; such contacts follow RP-014."},
 {"id": "RP-027", "category": "regulatory_reference", "effective_date": "2026-08-01", "owner": "Head of Wealth Compliance",
  "title": "Investment Suitability and KYC Refresh",
  "content": "SCOPE. Applies to every investment recommendation, including GIC renewals, registered-plan contributions and fund purchases.\n\nRULE 1 - CURRENT KYC. Know-your-client information (objectives, time horizon, risk tolerance, financial circumstances) must have been updated within the last 36 months. If it is older, every recommendation is paused until it is refreshed; only a KYC refresh contact may be made.\n\nRULE 2 - SUITABILITY. A recommendation must match the client's recorded risk profile (Conservative, Balanced or Growth) and put the client's interest first, consistent with the Client Focused Reforms.\n\nRULE 3 - LICENSED ADVISOR. Investment recommendations are made only by a licensed advisor. Other staff may refer and book appointments but may not recommend a specific investment.\n\nRULE 4 - NO RETURN PROMISES. Communications never promise or project returns, never call an investment risk-free, and never use the word guaranteed except as part of the product name of a guaranteed investment certificate in its disclosure (RP-016). Use 'GIC' in client copy."},
 {"id": "RP-028", "category": "approval_requirement", "effective_date": "2026-08-01", "owner": "Head of Registered Plans",
  "title": "Registered Plans - TFSA, RRSP, FHSA, RESP",
  "content": "SCOPE. Applies to recommending, opening or contributing to a TFSA, RRSP, FHSA or RESP.\n\nRULE 1 - ELIGIBILITY. FHSA: Canadian resident aged 18 to 70 who is a first-time home buyer (has not lived in a home they owned in the current or previous four calendar years) - clients who hold a mortgage on their home are NOT eligible. RESP: the beneficiary must be a child with a Social Insurance Number. TFSA: 18 or older with room available.\n\nRULE 2 - GRANT MECHANICS. The Canada Education Savings Grant (CESG) pays 20% of the first CAD 2,500 contributed per child per year (up to CAD 500), with lifetime limits; unused grant room carries forward one year at a time. Show the grant the family is not collecting, not a projected return.\n\nRULE 3 - OVER-CONTRIBUTION. Contributions above available room are taxed at 1% per month. Recommendations must use the room on record and remind the client to confirm it with their CRA account.\n\nRULE 4 - CONSENT AND SUITABILITY. Promotional registered-plan messages follow RP-011 consent rules and are suppressed for Vulnerable clients (RP-012). Any investment inside the plan requires current KYC (RP-027)."},
 {"id": "RP-029", "category": "approval_requirement", "effective_date": "2026-08-01", "owner": "Head of Newcomer Banking",
  "title": "Newcomer Banking - Packages and Credit Building",
  "content": "SCOPE. Applies to clients who arrived in Canada within the last 60 months (permanent residents, work-permit and study-permit holders), the newcomer banking package and newcomer credit-building products.\n\nRULE 1 - FEE-FREE PERIOD DISCLOSURE. The newcomer package's fee-free period and its end date are disclosed at opening and again at least 30 days before it ends, together with the monthly fee of the package that will apply next. Advisors recommend the lowest-cost package that fits the client's recorded usage (RP-023); changing package carries no fee.\n\nRULE 2 - STATUS-BASED ELIGIBILITY. Eligibility is based on the client's immigration status and identification documents only (e.g. permanent resident card, work or study permit). Never ask for information not needed for the product, and never make an account conditional on buying another product.\n\nRULE 3 - CREDIT BUILDING. A client with a secured card held for 12 months or more and every payment made on time may be offered an unsecured card, subject to adjudication; the security deposit is returned on graduation. Offers follow RP-011 consent, are suppressed for Vulnerable clients (RP-012) and are paused during an open fraud case (RP-032). Mortgage conversations require permanent-resident status or an eligible program, a credit file of at least 24 months and an affordability review (RP-013).\n\nRULE 4 - PLAIN LANGUAGE AND NO PRESSURE. Communications use plain language; multilingual support and interpreters are offered on request. Never use urgency or imply that a product is required to stay in Canada or to build credit."},
 {"id": "RP-030", "category": "regulatory_reference", "effective_date": "2026-08-01", "owner": "Head of Payments and International Transfers",
  "title": "International Money Transfers - Cost Disclosure and Scam Protection",
  "content": "SCOPE. Applies to every international money transfer and to any communication that compares transfer costs.\n\nRULE 1 - TOTAL COST BEFORE SENDING. Before a client confirms a transfer, show the transfer fee, the exchange rate and the exchange-rate (FX) margin applied, the total cost in Canadian dollars, the amount the recipient will receive and the expected delivery time. Any cost comparison must show fees plus FX margin as one total cost - never the fee alone.\n\nRULE 2 - NO SECRETS. Staff and Bank communications never ask for a PIN, passcode, password or one-time code, and never ask a client to move money to keep it safe.\n\nRULE 3 - SCAM WARNINGS. A scam warning is shown before the first transfer to any new recipient. Clients who send frequently to new recipients on a corridor named in a current fraud bulletin receive scam-awareness education and recipient verification (RP-022) - as a service conversation, never combined with a sales offer.\n\nRULE 4 - FAIR TREATMENT. Scam-risk outreach is driven by transaction behaviour and current fraud bulletins, never by a client's nationality or origin alone."},
 {"id": "RP-031", "category": "approval_requirement", "effective_date": "2026-08-01", "owner": "Head of Creditor Insurance",
  "title": "Creditor and Optional Insurance Sales",
  "content": "SCOPE. Applies to mortgage life and disability insurance, line of credit protection, card balance protection and any other optional insurance offered alongside credit, plus home and travel insurance discussions.\n\nRULE 1 - OPTIONAL, NEVER A CONDITION. Insurance is optional and is never a condition of approving, renewing or pricing any credit. Every insurance marketing message must say 'insurance is optional'. Never describe cover as required, mandatory or compulsory.\n\nRULE 2 - SUITABILITY AND DISCLOSURE. Before a client buys cover, explain what is and is not covered, the premium and how it changes, the effect of pre-existing conditions (health questions are assessed at claim time for some products), and compare it with cover the client may already have. Premiums must be affordable: do not market new cover to a household above the 44% TDS guideline (RP-013) or to a Vulnerable client (RP-012).\n\nRULE 3 - COOLING-OFF. The client may cancel within 30 days of purchase for a full refund. After that, cancellation is always free and takes effect at the client's instruction - the Bank never cancels cover on the client's behalf to save premiums, and reviews it with the client instead.\n\nRULE 4 - NO BUNDLING PRESSURE, AUTHORISED STAFF. No bundling pressure or tied selling. Only licensed or authorised staff discuss insurance; other staff may refer. Lapses are followed up to confirm they were intended. Travel-cover reminders are information only."},
 {"id": "RP-032", "category": "risk_consideration", "effective_date": "2026-08-01", "owner": "Chief Fraud Officer",
  "title": "Fraud Prevention, Scam Response and Elder/Vulnerable Client Protection",
  "content": "SCOPE. Applies to every contact about fraud alerts, scams, suspicious transfers, account takeover and security settings, and to every client with an open security event.\n\nRULE 1 - VERIFIED CHANNELS ONLY. Contact the client only through verified channels: the phone number and email on file before the event. If contact details changed during a security event, do not email - call the verified number on file. Ask the client to call the number on the back of their card or on the official website, never a number or link from a text or email.\n\nRULE 2 - NEVER ASK FOR SECRETS. Every security message says: 'We will never ask for your PIN, passcode or password.' Staff never ask for a one-time code and never ask a client to move money to keep it safe.\n\nRULE 3 - OLDER AND VULNERABLE CLIENTS. Offer a trusted contact person the Bank may reach if it suspects financial abuse. For large transfers to a new payee, use hold-and-verify: pause the transfer and confirm it with the client by a verified call-back before release. Stretched and Vulnerable clients with a scam-type event receive scam coaching (RP-012).\n\nRULE 4 - SECURITY BEFORE SALES. No marketing or product offer in any security communication. While a client has an open security event, promotional outreach in every book is paused until the event is resolved."},
]
docs = json.loads(P.read_text(encoding="utf-8"))
docs = [d for d in docs if d["id"] not in {n["id"] for n in NEW}] + [{k: d[k] for k in ("id", "title", "category", "effective_date", "owner", "content")} for d in NEW]
docs.sort(key=lambda d: d["id"])
P.write_text(json.dumps(docs, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
print(len(docs), "policies:", ", ".join(d["id"] for d in docs[-10:]))
